import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingList from "../components/BookingList";
import BookingForm from "../components/BookingForm";
import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import RejectModal from "../components/RejectModal";
import Sidebar from "../components/Sidebar";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";

const initialStats = {
  total: 0,
  pending: 0,
  approved: 0,
  rejected: 0,
};

const ClientDashboard = ({ view = "overview" }) => {
  const navigate = useNavigate();
  const { incharges } = useAppContext();

  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState(initialStats);
  const [loading, setLoading] = useState(true);
  const [showIncharges, setShowIncharges] = useState(false);

  // 🔥 FIXED MENU ITEMS (MATCH ROUTES)
  const menuItems = useMemo(
    () => [
      { key: "overview", label: "Overview", to: "/", icon: "🏠" },
      { key: "new", label: "New Booking", to: "/new-booking", icon: "➕" },
      { key: "bookings", label: "My Bookings", to: "/my-bookings", icon: "📋" },
      { key: "incharges", label: "Incharges", icon: "👨‍💼" },
    ],
    []
  );

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  const fetchDashboard = useCallback(async () => {
    try {
      const [dashboardRes, bookingsRes] = await Promise.all([
        api.get("/client/dashboard"),
        api.get("/client/bookings"),
      ]);

      setStats(dashboardRes.data || initialStats);
      setBookings(bookingsRes.data || []);
    } catch (err) {
      if (err.response?.status === 401) {
        localStorage.clear();
        navigate("/login");
      }
    } finally {
      setLoading(false);
    }
  }, [navigate]);

  useEffect(() => {
    fetchDashboard();
  }, [fetchDashboard]);

  const recentBookings = bookings.slice(0, 3);

  return (
    <div className="dashboard-shell">
      {/* SIDEBAR */}
      <Sidebar
        role="Client"
        items={menuItems}
        onLogout={handleLogout}
        onSelect={(key) => key === "incharges" && setShowIncharges(true)}
      />

      <main className="dashboard-main">
        <Navbar title="Client Dashboard" />

        {loading ? (
          <p>Loading...</p>
        ) : (
          <>
            {/* 🔥 VIEW SWITCH FIX */}
            {view === "overview" && (
              <>
                <section className="stats-grid">
                  <div className="card"><p>Total</p><h2>{stats.total}</h2></div>
                  <div className="card"><p>Pending</p><h2>{stats.pending}</h2></div>
                  <div className="card"><p>Approved</p><h2>{stats.approved}</h2></div>
                  <div className="card"><p>Rejected</p><h2>{stats.rejected}</h2></div>
                </section>

                <BookingList bookings={recentBookings} />
              </>
            )}

            {view === "new-booking" && (
              <BookingForm />
            )}

            {view === "my-bookings" && (
              <BookingList bookings={bookings} />
            )}
          </>
        )}
      </main>

      <InchargeModal
        open={showIncharges}
        groups={incharges}
        onClose={() => setShowIncharges(false)}
      />
    </div>
  );
};

export default ClientDashboard;
